pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ACCURAL_DEPOSIT} from "../src/ACCURAL_DEPOSIT.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ACCURAL_DEPOSIT c;

    function setUp() public {
        c = new ACCURAL_DEPOSIT();
    }

    function _run(uint256 _val) internal {
        _val = bound(_val, 0, 9);
        bool revertedBefore;
        try c.SetMinSum(_val) { revertedBefore = false; } catch { revertedBefore = true; }
        uint256 readBefore;
        try c.MinSum() returns (uint256 __r) { readBefore = __r; } catch { return; }
        bool revertedAfter;
        try c.SetMinSum(_val) { revertedAfter = false; } catch { revertedAfter = true; }
        uint256 readAfter;
        try c.MinSum() returns (uint256 __r) { readAfter = __r; } catch { return; }
        assertTrue(!revertedBefore && !revertedAfter && readBefore == _val && readAfter == _val);
    }

    function testFuzz_run(uint256 _val) public {
        _run(_val);
    }

    receive() external payable {}
}
